const scena = document.getElementById("scena");
const items = [...scena.querySelectorAll(".item")];
let active = null;

const IS_TOUCH = window.matchMedia("(hover: none) and (pointer: coarse)").matches;

function hit(item, clientX, clientY, big) {
  const r = item.getBoundingClientRect(); 
  let u = (clientX - r.left) / r.width;
  let v = (clientY - r.top) / r.height;
  let key = item.id;
  if (big) {
    const [bx, by, bw, bh] = item.dataset.bigBox.split(" ").map(Number);
    u = (u - bx) / bw;
    v = (v - by) / bh;
    key = item.id + "_big";
  }
  if (u < 0 || u >= 1 || v < 0 || v >= 1) return false;
  const rows = MASKS[key];
  const row = rows[Math.floor(v * rows.length)];
  return row[Math.floor(u * row.length)] === "1";
}

function pick(clientX, clientY) {
  if (active && active.dataset.bigBox && hit(active, clientX, clientY, true)) return active;
  for (let i = items.length - 1; i >= 0; i--) {
    if (hit(items[i], clientX, clientY, false)) return items[i];
  }
  return null;
}

function setActive(item) {
  if (item === active) return;
  if (active) active.classList.remove("is-active");
  active = item;
  if (active) active.classList.add("is-active");
  scena.style.cursor = active ? "pointer" : "";
}

if (!IS_TOUCH) {
  scena.addEventListener("pointermove", (e) => setActive(pick(e.clientX, e.clientY)));
  scena.addEventListener("pointerleave", () => setActive(null));
}

scena.addEventListener("click", (e) => {
  const item = pick(e.clientX, e.clientY);
  if (item) item.click(); 
});

if (IS_TOUCH) {
  const scroller = document.body;
  const hintL = document.getElementById("hint-left");
  const hintR = document.getElementById("hint-right");

  function updateHints() {
    const max = scroller.scrollWidth - scroller.clientWidth;
    hintL.classList.toggle("is-hidden", scroller.scrollLeft <= 4);
    hintR.classList.toggle("is-hidden", scroller.scrollLeft >= max - 4);
  }

  function centerScene() {
    scroller.scrollLeft = (scroller.scrollWidth - scroller.clientWidth) / 2;
    updateHints();
  }

  scroller.addEventListener("scroll", updateHints, { passive: true });
  window.addEventListener("resize", updateHints);
  window.addEventListener("load", centerScene);
  centerScene();
}
